import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)

    def _expired(self, expires_at):
        return expires_at is not None and self.clock() >= expires_at

    def _purge(self):
        if self.ttl is None:
            return
        now = self.clock()
        expired = [k for k, (_, exp) in self._data.items() if exp is not None and now >= exp]
        for k in expired:
            del self._data[k]

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, exp = entry
        if exp is not None and self.clock() >= exp:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        self._purge()
        exp = None if self.ttl is None else self.clock() + self.ttl
        self._data[key] = (value, exp)
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        self._purge()
        return len(self._data)

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        _, exp = entry
        if exp is not None and self.clock() >= exp:
            del self._data[key]
            return False
        return True
```

Wait — in put, if we first purge and then insert, we insert the key and evict. But what if we're replacing an expired key… it gets removed by purge, then reinserted. Good.

One subtle point: in put, after purge, insert; if key already existed, it retains its position, but move_to_end fixes that. Actually, in Python 3.8+ (I think 3.7's dict ordering guarantees it… actually move_to_end after assignment) `self._data[key] = ...` preserves position if the key exists. move_to_end handles the recency. Actually assigning to an existing key in an OrderedDict doesn't change the order, so move_to_end is needed. Correct.

Also, put could compute `now` once for both purge and exp. Minor point. Use a single `now = self.clock()` in put: purge with that now, and exp = now + ttl. That's fine, but purge uses its own clock call — clock is mostly monotonic; no problem.

